import { CustomerAddressesModel } from '@/account/data/models';
import normalizeGetAddressData from '@/account/lib/normalizeGetAddressData';

export const isEmpty = (obj: any): boolean => {
  if (obj === undefined || obj === null) return true;
  if (typeof obj !== 'object') return false;
  return Object.keys(obj).length === 0 || Object.values(obj).every(isEmpty);
};

export const sanitizeB2BCheckoutAddressPayload = (
  payloadData: Record<string, any>
): Record<string, any> => {
  const region = payloadData?.region;

  if (!region || typeof region !== 'object') {
    return payloadData;
  }

  const sanitizedRegion = { ...region } as Record<string, any>;
  const rawRegionId = sanitizedRegion.regionId;

  if (
    rawRegionId === '' ||
    rawRegionId === null ||
    rawRegionId === undefined
  ) {
    delete sanitizedRegion.regionId;
  } else if (typeof rawRegionId === 'string') {
    const trimmedRegionId = rawRegionId.trim();

    if (!trimmedRegionId || !/^\d+$/.test(trimmedRegionId)) {
      delete sanitizedRegion.regionId;
    } else {
      sanitizedRegion.regionId = Number(trimmedRegionId);
    }
  } else if (typeof rawRegionId === 'number' && !Number.isFinite(rawRegionId)) {
    delete sanitizedRegion.regionId;
  }

  return {
    ...payloadData,
    region: sanitizedRegion,
  };
};

export const resolveAddressSelectionPayloadData = ({
  item,
  isCheckoutContext,
  selectable,
  isB2BFlow,
}: {
  item?: CustomerAddressesModel;
  isCheckoutContext: boolean;
  selectable?: boolean;
  isB2BFlow: boolean;
}) => {
  const normalizedData = normalizeGetAddressData(item);

  if (isCheckoutContext && selectable && isB2BFlow) {
    const payload = { ...(normalizedData as Record<string, any>) };

    // Hand the selected address to checkout as a COMPANY address reference.
    // When the company address book is enabled the backend rejects both a new
    // address payload ("Use a company address instead") and a customer address
    // ("Customer address cannot be used when the company address book is
    // enabled") — it only accepts `company_address_id`, which is this id.
    // `id` is dropped so downstream can't mistake it for a customer address;
    // the remaining fields stay for display and address events.
    if (payload.id) {
      payload.companyAddressId = payload.id;
    }
    delete payload.id;

    const sanitizedPayload = sanitizeB2BCheckoutAddressPayload(payload);

    return {
      selectedItem: item,
      data: sanitizedPayload,
    };
  }

  return {
    selectedItem: item,
    data: normalizedData,
  };
};