import { FunctionComponent } from 'preact';
import { useId } from 'preact/compat';
import { useRef, useState } from 'preact/hooks';
import { classes, Container, Slot } from '@adobe-commerce/elsie/lib';
import {
  CardLoader,
  EmptyList,
  OrdersListAction,
  OrdersListCard,
} from '@/account/components';
import {
  Button,
  Field,
  Header,
  InLineAlert,
  Input,
  type InputProps,
  LiveRegion,
  Pagination,
  Picker,
} from '@adobe-commerce/elsie/components';
import { Close, Search } from '@adobe-commerce/elsie/icons';
import { useOrdersList } from '@/account/hooks/containers/useOrdersList';
import { useInLineAlert } from '@/account/hooks/useInLineAlert';
import { OrdersListWrapperProps } from '@/account/types';
import { useText } from '@adobe-commerce/elsie/i18n';
import {
  ORDER_SEARCH_MAX_LENGTH,
  ORDER_SEARCH_MIN_LENGTH,
} from '@/account/configs/orderSearch.config';
import '@/account/components/OrdersListWrapper/OrdersListWrapper.css';
import { useOrderSelectList } from '@/account/hooks/containers/useOrderSelectList';

interface OrderSearchInputProps extends InputProps {
  actionLabel: string;
  actionDisabled: boolean;
  clearLabel: string;
  onClear: () => void;
}

interface OrderSearchProps {
  handleSearch: (value: string) => void;
  refetchOrders: () => void;
  searchText: string;
}

const OrderSearchInput: FunctionComponent<OrderSearchInputProps> = ({
  actionLabel,
  actionDisabled,
  clearLabel,
  onClear,
  error,
  ...inputProps
}) => (
  <div
    className={classes([
      'account-orders-list__search-input',
      ['account-orders-list__search-input--has-clear', !actionDisabled],
      ['account-orders-list__search-input--error', !!error],
    ])}
  >
    <Input {...inputProps} error={error} aria-invalid={!!error} />
    <div className="account-orders-list__search-actions">
      {!actionDisabled ? (
        <Button
          className="account-orders-list__search-clear"
          type="button"
          variant="tertiary"
          icon={<Close />}
          aria-label={clearLabel}
          onClick={onClear}
        />
      ) : null}
      <Button
        className="account-orders-list__search-submit"
        type="submit"
        variant="tertiary"
        icon={<Search />}
        aria-label={actionLabel}
        disabled={actionDisabled}
      />
    </div>
  </div>
);

const OrderSearch: FunctionComponent<OrderSearchProps> = ({
  handleSearch,
  refetchOrders,
  searchText,
}) => {
  const translations = useText({
    action: 'Account.fullSizeView.OrdersList.OrdersListSearch.action',
    clear: 'Account.fullSizeView.OrdersList.OrdersListSearch.clear',
    label: 'Account.fullSizeView.OrdersList.OrdersListSearch.label',
    minimumLength:
      'Account.fullSizeView.OrdersList.OrdersListSearch.minimumLength',
    placeholder: 'Account.fullSizeView.OrdersList.OrdersListSearch.placeholder',
  });
  const [searchInput, setSearchInput] = useState(searchText);
  const [searchError, setSearchError] = useState('');
  const searchFormRef = useRef<HTMLFormElement>(null);
  const searchInputId = `${useId()}-order-search`;
  const hasSearchTerm = Boolean(searchInput.trim() || searchText);

  const applySearch = (term: string) => {
    setSearchError('');
    setSearchInput(term);

    if (term !== searchText) {
      handleSearch(term);
    } else if (term) {
      // re-submitting the same term refreshes the current results
      refetchOrders();
    }
  };

  const runSearch = () => {
    const term = searchInput.trim();

    if (term.length > 0 && term.length < ORDER_SEARCH_MIN_LENGTH) {
      setSearchError(translations.minimumLength);
      return;
    }

    applySearch(term);
  };

  const clearSearch = () => {
    applySearch('');

    const input = searchFormRef.current?.elements.namedItem('orderSearch');

    if (input instanceof HTMLInputElement) {
      input.focus();
    }
  };

  return (
    <form
      ref={searchFormRef}
      className="account-orders-list__search"
      role="search"
      aria-label={translations.action}
      onSubmit={(event) => {
        event.preventDefault();
        runSearch();
      }}
    >
      <Field label={translations.label} error={searchError || undefined}>
        <OrderSearchInput
          id={searchInputId}
          name="orderSearch"
          value={searchInput}
          maxLength={ORDER_SEARCH_MAX_LENGTH}
          placeholder={translations.placeholder}
          actionLabel={translations.action}
          actionDisabled={!hasSearchTerm}
          clearLabel={translations.clear}
          onClear={clearSearch}
          onInput={(event) => {
            setSearchInput(event.currentTarget.value);
            setSearchError('');
          }}
        />
      </Field>
    </form>
  );
};

export const OrdersListWrapper: Container<OrdersListWrapperProps> = ({
  className,
  withHeader = true,
  minifiedView = false,
  withThumbnails = true,
  withFilter = true,
  withSearch = false,
  searchScope = 'selectedDate',
  ordersInMinifiedView = 1,
  pageSize = 10,
  routeOrdersList,
  routeOrderDetails,
  routeReturnDetails,
  routeTracking,
  routeOrderProduct,
  slots,
}) => {
  const minifiedViewKey = minifiedView ? 'minifiedView' : 'fullSizeView';

  const translations = useText({
    containerTitle: `Account.${minifiedViewKey}.OrdersList.containerTitle`,
    dateOrderPlaced: `Account.${minifiedViewKey}.OrdersList.dateOrderPlaced`,
    loading: 'Account.OrdersList.loading',
    loaded: 'Account.OrdersList.loaded',
  });

  const {
    selectableDateList,
    selectedDate,
    handleSelectDate,
    selectedPage,
    searchText,
    handleSearch,
    setSelectedPage,
    handleSetFirstOrderDate,
  } = useOrderSelectList(searchScope);

  const { inLineAlertProps, handleSetInLineAlert } = useInLineAlert();

  const {
    pageInfo,
    loading,
    orderHistoryListItems,
    placeholderImage,
    refetchOrders,
  } = useOrdersList({
    minifiedView,
    pageSize,
    ordersInMinifiedView,
    selectedDate,
    selectedPage,
    searchText,
    handleSetFirstOrderDate,
    handleSetInLineAlert,
  });

  return (
    <div>
      {withHeader ? (
        <Header
          aria-label={translations.containerTitle}
          role="region"
          title={translations.containerTitle}
          divider={!minifiedView}
          className={classes([
            'account-orders-list-header-title',
            ['account-orders-list-header', minifiedView],
          ])}
          level={minifiedView ? 2 : 1}
        />
      ) : null}

      <div className={classes(['account-orders-list', className])}>
        <LiveRegion
          message={loading ? translations.loading : translations.loaded}
        />
        {!minifiedView && (withSearch || withFilter) ? (
          <div className={'account-orders-list__controls'}>
            {withFilter ? (
              <Field
                className="account-orders-list__date-select"
                label={translations.dateOrderPlaced}
              >
                <Picker
                  id="orderDatePicker"
                  value={selectedDate}
                  name="orderDatePicker"
                  aria-label={translations.dateOrderPlaced}
                  options={selectableDateList}
                  handleSelect={handleSelectDate}
                />
              </Field>
            ) : null}

            {withSearch ? (
              <OrderSearch
                handleSearch={handleSearch}
                refetchOrders={refetchOrders}
                searchText={searchText}
              />
            ) : null}
          </div>
        ) : null}

        {inLineAlertProps.text ? (
          <InLineAlert
            data-testid="ordersListInLineAlert"
            className="account-orders-list__notification"
            type={inLineAlertProps.type}
            variant="secondary"
            heading={inLineAlertProps.text}
            icon={inLineAlertProps.icon}
          />
        ) : null}

        {!loading ? (
          <>
            {orderHistoryListItems.length ? (
              <>
                {orderHistoryListItems.map((el, index) => {
                  return (
                    <OrdersListCard
                      placeholderImage={placeholderImage}
                      routeTracking={routeTracking}
                      routeOrderProduct={routeOrderProduct}
                      routeReturnDetails={routeReturnDetails}
                      minifiedView={minifiedView}
                      item={el}
                      withThumbnails={withThumbnails}
                      key={index}
                      slots={slots}
                    >
                      {slots?.OrdersListAction ? (
                        <Slot
                          data-testid={`ordersListActionSlot_${index}`}
                          name="OrdersListAction"
                          slot={slots?.OrdersListAction}
                          context={{ orderHistoryListItem: el }}
                        />
                      ) : (
                        <OrdersListAction
                          minifiedView={minifiedView}
                          orderNumber={el.number}
                          orderToken={el.token}
                          routeOrderDetails={routeOrderDetails}
                        />
                      )}
                    </OrdersListCard>
                  );
                })}
              </>
            ) : (
              <EmptyList
                isEmpty={!orderHistoryListItems.length}
                typeList="orders"
                minifiedView={minifiedView}
              />
            )}
          </>
        ) : (
          <>
            {Array.from(Array(pageInfo?.pageSize).keys()).map((i) => (
              <CardLoader
                testId={'orderSkeletonLoader'}
                withCard={false}
                key={i}
              />
            ))}
          </>
        )}
        {!minifiedView && pageInfo?.totalPages > 1 ? (
          <Pagination
            totalPages={pageInfo?.totalPages}
            currentPage={selectedPage}
            onChange={setSelectedPage}
          />
        ) : null}

        {minifiedView ? (
          <OrdersListAction
            minifiedView={minifiedView}
            routeOrdersList={routeOrdersList}
          />
        ) : null}
      </div>
    </div>
  );
};
