import {
  createCustomerAddress,
  getAttributesForm,
  updateCustomerAddress,
  getCountries,
  createCompanyAddress,
  updateCompanyAddress,
  setDefaultCompanyAddress,
} from '@/account/api';
import {
  defaultNicknameField,
  defaultShippingCheckBox,
  defaultBillingCheckBox,
  defaultAddressTypeShippingCheckBox,
  defaultAddressTypeBillingCheckBox,
  defaultIsDefaultCheckBox,
} from '@/account/configs/addressField.config';
import {
  AttributesFormModel,
  Country,
  CustomerAddressesModel,
  FieldEnumList,
} from '@/account/data/models';
import type { CompanyAddressType } from '@/account/types/api/companyAddress.types';
import { getFieldsConfig } from '@/account/lib/getFieldsConfig';
import { getFormValues } from '@/account/lib/getFormValues';
import prepareNormalizedData from '@/account/lib/prepareNormalizedData';
import { serializeAddressForm } from '@/account/lib/serializeAddressForm';
import transformSessionData from '@/account/lib/transformSessionData';
import {
  AddressValidationAlertKey,
  canSetAddressAsDefault,
  canSetDefaultAddressInForm,
  getSanitizedAddressPayload,
  resolveAddressFormErrorMessage,
  resolveB2BDefaultCheckBoxRules,
  resolveCreateAddressAlertKey,
  resolveShouldEnforceB2BPermissions,
  resolveTemporaryCheckoutAddressMode,
  resolveUpdateAddressAlertKey,
} from '@/account/lib/addressFormRules';
import { useAddressFormProps } from '@/account/types';
import { useText } from '@adobe-commerce/elsie/i18n';
import { VNode } from 'preact';
import { HTMLAttributes } from 'preact/compat';
import { useCallback, useEffect, useMemo, useState } from 'preact/hooks';

export const findNonEmptyObject = (
  obj1: Record<string, unknown> | undefined,
  obj2: CustomerAddressesModel | undefined
): CustomerAddressesModel | Record<string, unknown> => {
  if (obj1 && Object.keys(obj1).length > 0) {
    return obj1;
  }

  if (obj2 && Object.keys(obj2).length > 0) {
    return obj2;
  }

  return {};
};

const isNicknameField = (field?: Partial<AttributesFormModel>): boolean =>
  field?.name === 'nickname' ||
  field?.code === 'nickname' ||
  field?.customUpperCode === 'nickname';

export const useAddressForm = ({
  showFormLoader,
  showSaveCheckBox,
  saveCheckBoxValue,
  addressFormId,
  billingCheckBoxValue,
  shippingCheckBoxValue,
  showShippingCheckBox,
  showBillingCheckBox,
  hasDefaultShippingAddress,
  hasDefaultBillingAddress,
  inputsDefaultValueSet,
  onCloseBtnClick,
  onSuccess,
  onError,
  formName,
  isB2BFlow,
  enforceB2BPermissions,
  permissions,
}: useAddressFormProps) => {
  const translations = useText({
    noPermissionEditAddresses:
      'Account.AddressForm.notifications.noPermissionEditAddresses',
    noPermissionCreateAddresses:
      'Account.AddressForm.notifications.noPermissionCreateAddresses',
    companyAddressSingleDefaultType:
      'Account.AddressForm.notifications.companyAddressSingleDefaultType',
    b2bShippingTypeLabel: 'Account.AddressForm.formText.b2bShippingTypeLabel',
    b2bBillingTypeLabel: 'Account.AddressForm.formText.b2bBillingTypeLabel',
    b2bIsDefaultLabel: 'Account.AddressForm.formText.b2bIsDefaultLabel',
    b2bIsDefaultShippingLabel:
      'Account.AddressForm.formText.b2bIsDefaultShippingLabel',
    b2bIsDefaultBillingLabel:
      'Account.AddressForm.formText.b2bIsDefaultBillingLabel',
  });

  const shouldEnforceB2BPermissions = resolveShouldEnforceB2BPermissions(
    isB2BFlow,
    enforceB2BPermissions
  );
  const isTemporaryCheckoutAddressMode = resolveTemporaryCheckoutAddressMode({
    isB2BFlow,
    shouldEnforceB2BPermissions,
    permissions,
  });

  const [inLineAlert, setInLineAlert] = useState<{
    text: string;
    type: 'success' | 'warning' | 'error';
    icon?: VNode<HTMLAttributes<SVGSVGElement>>;
  }>({
    text: '',
    type: 'success',
  });
  const [submitLoading, setSubmitLoading] = useState(showFormLoader ?? false);
  const [addressId, setAddressId] = useState<string>(addressFormId || '');
  const [attributesFormList, setAttributesFormList] = useState<
    AttributesFormModel[]
  >([]);
  const [countriesData, setCountriesData] = useState<{
    availableCountries: Country[];
    countriesWithRequiredRegion: string[];
    optionalZipCountries: string[];
  } | null>(null);
  const [inputChange, setInputChange] = useState(() => {
    const savedData = sessionStorage.getItem(`${formName}_addressData`);
    return savedData
      ? { countryCode: JSON.parse(savedData)?.data?.countryCode }
      : inputsDefaultValueSet;
  });
  const [disableField, setDisableField] = useState(false);
  const [saveCheckBoxAddress, setSaveCheckBoxAddress] = useState<boolean>(
    () => {
      const sessionAddressForm = sessionStorage.getItem(
        `${formName}_addressData`
      );

      const sessionAddressFormData = sessionAddressForm
        ? JSON.parse(sessionAddressForm)?.data?.['saveAddressBook']
        : (saveCheckBoxValue as boolean);

      return sessionAddressFormData;
    }
  );
  const canEditAddressInCurrentMode =
    !shouldEnforceB2BPermissions || Boolean(permissions?.canEditAddress);
  const canSetDefaultAddressInCurrentMode =
    !shouldEnforceB2BPermissions || Boolean(permissions?.canSetDefaultAddress);
  const isB2BEditMode = Boolean(isB2BFlow && addressId);
  const isSetDefaultOnlyEditMode =
    isB2BEditMode &&
    shouldEnforceB2BPermissions &&
    !canEditAddressInCurrentMode &&
    canSetDefaultAddressInCurrentMode;
  const isAddressTypeSelectionOnlyMode =
    isB2BEditMode &&
    shouldEnforceB2BPermissions &&
    canEditAddressInCurrentMode &&
    !canSetDefaultAddressInCurrentMode;

  const handleSaveCheckBoxAddress = useCallback((event: Event) => {
    setSaveCheckBoxAddress((event.target as HTMLInputElement).checked);
  }, []);

  useEffect(() => {
    if (typeof showFormLoader === 'undefined') return;
    setSubmitLoading(showFormLoader);
  }, [showFormLoader]);

  useEffect(() => {
    getAttributesForm(
      addressId ? 'customer_address_edit' : 'customer_register_address'
    ).then((attributeFormResponse) => {
      setAttributesFormList(attributeFormResponse);
    });
  }, [addressId]);

  useEffect(() => {
    setDisableField(true);
    getCountries().then(
      ({
        availableCountries,
        countriesWithRequiredRegion,
        optionalZipCountries,
      }) => {
        setCountriesData({
          availableCountries,
          countriesWithRequiredRegion,
          optionalZipCountries,
        });
        setDisableField(false);
      }
    );
  }, []);

  const countryOptions = useMemo(() => {
    return countriesData?.availableCountries || [];
  }, [countriesData]);

  const isRequiredRegion = useMemo(() => {
    if (!inputChange?.countryCode || !countriesData) return false;
    return countriesData.countriesWithRequiredRegion.includes(
      inputChange.countryCode as string
    );
  }, [inputChange?.countryCode, countriesData]);

  const isRequiredPostCode = useMemo(() => {
    if (!inputChange?.countryCode || !countriesData) return true;
    return !countriesData.optionalZipCountries.includes(
      inputChange.countryCode as string
    );
  }, [inputChange?.countryCode, countriesData]);

  const regionOptions = useMemo(() => {
    if (!inputChange?.countryCode || !countriesData) return [];

    const country = countriesData.availableCountries.find(
      (c) => c.value === inputChange.countryCode
    );

    return (
      country?.availableRegions?.map((region) => ({
        text: region.name,
        value: `${region.code},${region.id}`,
      })) || []
    );
  }, [inputChange?.countryCode, countriesData]);

  const handleOnCloseForm = useCallback(() => {
    setInLineAlert({
      text: '',
      type: 'success',
    });
    onCloseBtnClick?.();
  }, [onCloseBtnClick]);

  const resolveSelectedAddressType = useCallback(
    (requestPayload: CustomerAddressesModel): CompanyAddressType => {
      if (requestPayload.addressType === 'BILLING') {
        return 'BILLING';
      }

      if (requestPayload.addressType === 'SHIPPING') {
        return 'SHIPPING';
      }

      if (
        requestPayload.addressTypeBilling &&
        !requestPayload.addressTypeShipping
      ) {
        return 'BILLING';
      }

      if (
        requestPayload.addressTypeShipping &&
        !requestPayload.addressTypeBilling
      ) {
        return 'SHIPPING';
      }

      if (requestPayload.defaultBilling && !requestPayload.defaultShipping) {
        return 'BILLING';
      }

      if (requestPayload.defaultShipping && !requestPayload.defaultBilling) {
        return 'SHIPPING';
      }

      return inputsDefaultValueSet?.addressType ?? 'SHIPPING';
    },
    [inputsDefaultValueSet?.addressType]
  );

  const resolveIsDefaultSelection = useCallback(
    (requestPayload: CustomerAddressesModel): boolean => {
      if (typeof requestPayload.isDefault === 'boolean') {
        return requestPayload.isDefault;
      }

      if (
        typeof requestPayload.defaultShipping === 'boolean' ||
        typeof requestPayload.defaultBilling === 'boolean'
      ) {
        return Boolean(
          requestPayload.defaultShipping || requestPayload.defaultBilling
        );
      }

      return Boolean(
        inputsDefaultValueSet?.defaultShipping ||
          inputsDefaultValueSet?.defaultBilling
      );
    },
    [inputsDefaultValueSet?.defaultBilling, inputsDefaultValueSet?.defaultShipping]
  );

  const handleUpdateAddress = useCallback(
    async (event: Event, valid: boolean): Promise<void | null | undefined> => {
      if (!valid) return null;

      const formValues = getFormValues(event.target as HTMLFormElement);
      const serializeValues = serializeAddressForm(formValues);
      const requestPayload: CustomerAddressesModel = {
        ...(serializeValues as CustomerAddressesModel),
      };
      const originalAddressType = inputsDefaultValueSet?.addressType;

      if (isB2BFlow) {
        const selectedAddressType = resolveSelectedAddressType(requestPayload);
        const selectedIsDefault = resolveIsDefaultSelection(requestPayload);
        const normalizedAddressType =
          isB2BEditMode && originalAddressType
            ? originalAddressType
            : selectedAddressType;

        requestPayload.addressType = normalizedAddressType;
        requestPayload.addressTypeShipping =
          normalizedAddressType === 'SHIPPING';
        requestPayload.addressTypeBilling = normalizedAddressType === 'BILLING';
        requestPayload.isDefault = selectedIsDefault;
        requestPayload.defaultShipping =
          normalizedAddressType === 'SHIPPING' ? selectedIsDefault : false;
        requestPayload.defaultBilling =
          normalizedAddressType === 'BILLING' ? selectedIsDefault : false;

      }

      if (isB2BFlow && isSetDefaultOnlyEditMode) {
        setSubmitLoading(true);

        try {
          if (requestPayload.isDefault) {
            await setDefaultCompanyAddress(addressId);
          }

          onSuccess?.();
          onCloseBtnClick?.();
          (event?.target as HTMLFormElement)?.reset();
        } catch (error) {
          const errorMessage = resolveAddressFormErrorMessage(error);

          setInLineAlert((prev) => ({
            ...prev,
            text: errorMessage,
            type: 'error',
          }));
          onError?.(errorMessage);
        } finally {
          setSubmitLoading(false);
        }

        return null;
      }

      const validationAlertKey = resolveUpdateAddressAlertKey({
        shouldEnforceB2BPermissions,
        canEditAddress: permissions?.canEditAddress,
        isB2BFlow,
        requestPayload,
      });

      if (validationAlertKey) {
        setInLineAlert((prev) => ({
          ...prev,
          text: translations[validationAlertKey as AddressValidationAlertKey],
          type: 'warning',
        }));

        return null;
      }

      setSubmitLoading(true);

      const sanitizedPayload = getSanitizedAddressPayload({
        requestPayload,
        shouldEnforceB2BPermissions,
        canSetDefaultAddress: permissions?.canSetDefaultAddress,
      });

      const b2bUpdatePayload = isB2BFlow
        ? {
            ...sanitizedPayload,
            isDefault: resolveIsDefaultSelection(requestPayload),
          }
        : sanitizedPayload;

      try {
        if (isB2BFlow) {
          // B2B: Use company address API
          const shouldSetAsDefault = canSetAddressAsDefault({
            requestPayload,
            shouldEnforceB2BPermissions,
            canSetDefaultAddress: permissions?.canSetDefaultAddress,
          });

          await updateCompanyAddress(addressId, b2bUpdatePayload);

          if (shouldSetAsDefault) {
            await setDefaultCompanyAddress(addressId);
          }
        } else {
          // B2C: Use customer address API
          const customerUpdatePayload: Parameters<
            typeof updateCustomerAddress
          >[0] = {
            ...sanitizedPayload,
            addressId: Number(addressId),
          };

          await updateCustomerAddress(customerUpdatePayload);
        }
        
        onSuccess?.();
        onCloseBtnClick?.();
        (event?.target as HTMLFormElement)?.reset();
      } catch (error) {
        const errorMessage = resolveAddressFormErrorMessage(error);

        setInLineAlert((prev) => ({
          ...prev,
          text: errorMessage,
          type: 'error',
        }));
        onError?.(errorMessage);
      } finally {
        setSubmitLoading(false);
      }
    },
    [
      onCloseBtnClick,
      onError,
      onSuccess,
      isB2BFlow,
      shouldEnforceB2BPermissions,
      translations,
      addressId,
      inputsDefaultValueSet,
      permissions?.canEditAddress,
      permissions?.canSetDefaultAddress,
      resolveSelectedAddressType,
      resolveIsDefaultSelection,
      isB2BEditMode,
      isSetDefaultOnlyEditMode,
    ]
  );

  const handleCreateAddress = useCallback(
    async (event: Event, valid: boolean): Promise<void | null | undefined> => {
      if (!valid) return;

      // eslint-disable-next-line @typescript-eslint/no-unused-vars
      const { saveAddressBook, ...formValues } = getFormValues(
        event.target as HTMLFormElement
      );

      const serializeValues = serializeAddressForm(formValues);
      const requestPayload: CustomerAddressesModel = {
        ...(serializeValues as CustomerAddressesModel),
      };

      if (isB2BFlow) {
        const selectedAddressType = resolveSelectedAddressType(requestPayload);
        const selectedIsDefault = resolveIsDefaultSelection(requestPayload);

        requestPayload.addressType = selectedAddressType;
        requestPayload.addressTypeShipping = selectedAddressType === 'SHIPPING';
        requestPayload.addressTypeBilling = selectedAddressType === 'BILLING';
        requestPayload.isDefault = selectedIsDefault;
        requestPayload.defaultShipping =
          selectedAddressType === 'SHIPPING' ? selectedIsDefault : false;
        requestPayload.defaultBilling =
          selectedAddressType === 'BILLING' ? selectedIsDefault : false;

      }

      setSubmitLoading(true);

      if (isTemporaryCheckoutAddressMode) {
        onSuccess?.();
        onCloseBtnClick?.();
        (event?.target as HTMLFormElement)?.reset();
        setAddressId('');
        setSubmitLoading(false);
        return null;
      }

      const validationAlertKey = resolveCreateAddressAlertKey({
        shouldEnforceB2BPermissions,
        canCreateAddress: permissions?.canCreateAddress,
        isB2BFlow,
        requestPayload,
      });

      if (validationAlertKey) {
        setInLineAlert((prev) => ({
          ...prev,
          text: translations[validationAlertKey as AddressValidationAlertKey],
          type: 'warning',
        }));

        setSubmitLoading(false);
        return null;
      }

      const sanitizedPayload = getSanitizedAddressPayload({
        requestPayload,
        shouldEnforceB2BPermissions,
        canSetDefaultAddress: permissions?.canSetDefaultAddress,
      });

      try {
        if (isB2BFlow) {
          // B2B: Use company address API
          const createdAddress = await createCompanyAddress(sanitizedPayload);

          if (
            canSetAddressAsDefault({
              requestPayload: sanitizedPayload,
              shouldEnforceB2BPermissions,
              canSetDefaultAddress: permissions?.canSetDefaultAddress,
            })
          ) {
            await setDefaultCompanyAddress(String(createdAddress?.id ?? ''));
          }
        } else {
          // B2C: Use customer address API
          await createCustomerAddress(sanitizedPayload);
        }
        
        onSuccess?.();
        onCloseBtnClick?.();
        (event?.target as HTMLFormElement)?.reset();
      } catch (error) {
        const errorMessage = resolveAddressFormErrorMessage(error);

        setInLineAlert((prev) => ({
          ...prev,
          text: errorMessage,
          type: 'error',
        }));
        onError?.(errorMessage);
      } finally {
        setAddressId('');
        setSubmitLoading(false);
      }
    },
    [
      onCloseBtnClick,
      onError,
      onSuccess,
      isB2BFlow,
      shouldEnforceB2BPermissions,
      isTemporaryCheckoutAddressMode,
      translations,
      permissions?.canCreateAddress,
      permissions?.canSetDefaultAddress,
      resolveSelectedAddressType,
      resolveIsDefaultSelection,
    ]
  );

  const b2bDefaultCheckBoxRules = useMemo(() => {
    return resolveB2BDefaultCheckBoxRules({
      isB2BFlow,
      showShippingCheckBox,
      showBillingCheckBox,
      shippingCheckBoxValue,
      billingCheckBoxValue,
      addressId,
      hasDefaultShippingAddress,
      hasDefaultBillingAddress,
    });
  }, [
    isB2BFlow,
    showShippingCheckBox,
    showBillingCheckBox,
    shippingCheckBoxValue,
    billingCheckBoxValue,
    addressId,
    hasDefaultShippingAddress,
    hasDefaultBillingAddress,
  ]);

  const normalizeFieldsConfig = useMemo(() => {
    if (!attributesFormList.length) return [];

    const hasRenderableNicknameField = attributesFormList.some(
      (field) =>
        isNicknameField(field) &&
        field.fieldType === FieldEnumList.TEXT &&
        !field.isHidden
    );

    const shouldForceNicknameField =
      isB2BFlow && !hasRenderableNicknameField;

    const normalizedAttributesFormList =
      shouldForceNicknameField
        ? [
            ...attributesFormList.filter((field) => !isNicknameField(field)),
            defaultNicknameField,
          ]
        : attributesFormList;

    const canSetDefaultAddress = canSetDefaultAddressInForm({
      isTemporaryCheckoutAddressMode,
      shouldEnforceB2BPermissions,
      canSetDefaultAddress: permissions?.canSetDefaultAddress,
    });
    const liveAddressTypeBilling = inputChange?.addressTypeBilling;
    const liveAddressTypeShipping = inputChange?.addressTypeShipping;
    const selectedAddressType =
      typeof liveAddressTypeBilling === 'boolean' ||
      typeof liveAddressTypeShipping === 'boolean'
        ? liveAddressTypeBilling
          ? 'BILLING'
          : 'SHIPPING'
        : inputsDefaultValueSet?.addressType ?? 'SHIPPING';
    const isDefaultAddressSelected = Boolean(
      inputsDefaultValueSet?.defaultShipping ||
        inputsDefaultValueSet?.defaultBilling
    );
    const isB2BTypeSelectionDisabled = Boolean(isB2BFlow && addressId);
    const isB2BIsDefaultDisabled =
      !canSetDefaultAddress ||
      isAddressTypeSelectionOnlyMode ||
      (isSetDefaultOnlyEditMode && isDefaultAddressSelected);
    const shouldHideB2BAddressOptions = Boolean(
      !shouldEnforceB2BPermissions ||
      isTemporaryCheckoutAddressMode ||
        (showSaveCheckBox && !saveCheckBoxAddress)
    );

    const shippingCheckBox = {
      ...defaultShippingCheckBox,
      defaultValue: b2bDefaultCheckBoxRules.shippingDefaultValue,
      isHidden: Boolean(
        showSaveCheckBox && !saveCheckBoxAddress
          ? true
          : !b2bDefaultCheckBoxRules.showShipping || !canSetDefaultAddress
      ),
    };

    const billingCheckBox = {
      ...defaultBillingCheckBox,
      defaultValue: b2bDefaultCheckBoxRules.billingDefaultValue,
      isHidden: Boolean(
        showSaveCheckBox && !saveCheckBoxAddress
          ? true
          : !b2bDefaultCheckBoxRules.showBilling || !canSetDefaultAddress
      ),
    };

    const b2bAddressTypeShippingCheckBox = {
      ...defaultAddressTypeShippingCheckBox,
      label: translations.b2bShippingTypeLabel,
      forceLabel: true,
      defaultValue: selectedAddressType === 'SHIPPING',
      isHidden: shouldHideB2BAddressOptions,
      disabled: isB2BTypeSelectionDisabled,
    };

    const b2bAddressTypeBillingCheckBox = {
      ...defaultAddressTypeBillingCheckBox,
      label: translations.b2bBillingTypeLabel,
      forceLabel: true,
      defaultValue: selectedAddressType === 'BILLING',
      isHidden: shouldHideB2BAddressOptions,
      disabled: isB2BTypeSelectionDisabled,
    };

    const b2bIsDefaultLabel =
      selectedAddressType === 'BILLING'
        ? translations.b2bIsDefaultBillingLabel
        : translations.b2bIsDefaultShippingLabel;

    const b2bIsDefaultCheckBox = {
      ...defaultIsDefaultCheckBox,
      label: b2bIsDefaultLabel,
      forceLabel: true,
      defaultValue: isDefaultAddressSelected,
      isHidden: shouldHideB2BAddressOptions,
      disabled: isB2BIsDefaultDisabled,
    };

    const updatedAttributesFormList = isB2BFlow
      ? [
          ...normalizedAttributesFormList,
          b2bAddressTypeShippingCheckBox,
          b2bAddressTypeBillingCheckBox,
          b2bIsDefaultCheckBox,
        ]
      : [...normalizedAttributesFormList, shippingCheckBox, billingCheckBox];

    const sessionAddressForm = sessionStorage.getItem(
      `${formName}_addressData`
    );

    const sessionAddressFormData = sessionAddressForm
      ? transformSessionData(
          JSON.parse(sessionAddressForm).data as CustomerAddressesModel,
          regionOptions
        )
      : {};

    const baseItemValues = findNonEmptyObject(
      sessionAddressFormData,
      inputsDefaultValueSet
    ) as Record<string, unknown>;
    const itemValuesForFields = isB2BFlow
      ? {
          ...baseItemValues,
          addressTypeShipping: selectedAddressType === 'SHIPPING',
          addressTypeBilling: selectedAddressType === 'BILLING',
          isDefault: isDefaultAddressSelected,
        }
      : baseItemValues;

    const fields = getFieldsConfig(itemValuesForFields, updatedAttributesFormList);

    const normalizedFields = prepareNormalizedData({
      fields,
      addressId,
      countryOptions,
      disableField,
      regionOptions,
      isRequiredRegion,
      isRequiredPostCode,
      keepDefaultCheckBoxesOnEdit: Boolean(isB2BFlow && addressId),
    });

    if (!isSetDefaultOnlyEditMode) {
      return normalizedFields;
    }

    return normalizedFields.map((field) => {
      const isB2BSelectionCheckBox =
        field.customUpperCode === 'addressTypeShipping' ||
        field.customUpperCode === 'addressTypeBilling' ||
        field.customUpperCode === 'isDefault';

      if (isB2BSelectionCheckBox) {
        return {
          ...field,
          disabled:
            field.customUpperCode === 'isDefault'
              ? isB2BIsDefaultDisabled
              : true,
        };
      }

      return {
        ...field,
        disabled: true,
      };
    });
  }, [
    attributesFormList,
    isB2BFlow,
    showSaveCheckBox,
    saveCheckBoxAddress,
    b2bDefaultCheckBoxRules,
    isTemporaryCheckoutAddressMode,
    shouldEnforceB2BPermissions,
    permissions?.canSetDefaultAddress,
    formName,
    regionOptions,
    inputsDefaultValueSet,
    addressId,
    countryOptions,
    disableField,
    isRequiredRegion,
    isRequiredPostCode,
    isSetDefaultOnlyEditMode,
    isAddressTypeSelectionOnlyMode,
    inputChange?.addressTypeShipping,
    inputChange?.addressTypeBilling,
    translations.b2bShippingTypeLabel,
    translations.b2bBillingTypeLabel,
    translations.b2bIsDefaultShippingLabel,
    translations.b2bIsDefaultBillingLabel,
  ]);

  const handleInputChange = useCallback(
    (values: Record<string, string | number | boolean>) => {
      setInputChange((prev) => ({ ...prev, ...values }));
    },
    []
  );

  return {
    regionOptions,
    saveCheckBoxAddress,
    inLineAlert,
    addressId,
    submitLoading,
    normalizeFieldsConfig,
    handleSaveCheckBoxAddress,
    handleUpdateAddress,
    handleCreateAddress,
    handleOnCloseForm,
    handleInputChange,
  };
};
