import { CustomerAddressesModel } from '@/account/data/models';

type AddressPermissionFlags = {
  canCreateAddress?: boolean;
  canSetDefaultAddress?: boolean;
  loading?: boolean;
};

export type B2BDefaultCheckBoxRules = {
  showShipping: boolean;
  showBilling: boolean;
  shippingDefaultValue: boolean;
  billingDefaultValue: boolean;
};

export type AddressValidationAlertKey =
  | 'noPermissionEditAddresses'
  | 'noPermissionCreateAddresses'
  | 'companyAddressSingleDefaultType';

export const resolveShouldEnforceB2BPermissions = (
  isB2BFlow?: boolean,
  enforceB2BPermissions?: boolean
): boolean => {
  return Boolean(isB2BFlow) && enforceB2BPermissions !== false;
};

export const resolveTemporaryCheckoutAddressMode = ({
  isB2BFlow,
  shouldEnforceB2BPermissions,
  permissions,
}: {
  isB2BFlow?: boolean;
  shouldEnforceB2BPermissions: boolean;
  permissions?: AddressPermissionFlags;
}): boolean => {
  return (
    Boolean(isB2BFlow) &&
    !shouldEnforceB2BPermissions &&
    permissions?.loading === false &&
    permissions?.canCreateAddress === false
  );
};

export const hasSingleDefaultTypeViolation = (
  isB2BFlow: boolean | undefined,
  requestPayload: CustomerAddressesModel
): boolean => {
  const hasConflictingTypeSelection =
    Boolean(requestPayload.addressTypeShipping) &&
    Boolean(requestPayload.addressTypeBilling);

  return (
    Boolean(isB2BFlow) &&
    (hasConflictingTypeSelection ||
      (Boolean(requestPayload.defaultShipping) &&
        Boolean(requestPayload.defaultBilling)))
  );
};

export const shouldOmitDefaultFlagsFromPayload = (
  shouldEnforceB2BPermissions: boolean,
  canSetDefaultAddress?: boolean
): boolean => {
  return shouldEnforceB2BPermissions && !canSetDefaultAddress;
};

export const canSetAddressAsDefault = ({
  requestPayload,
  shouldEnforceB2BPermissions,
  canSetDefaultAddress,
}: {
  requestPayload: CustomerAddressesModel;
  shouldEnforceB2BPermissions: boolean;
  canSetDefaultAddress?: boolean;
}): boolean => {
  const shouldSetAsDefault =
    typeof requestPayload.isDefault === 'boolean'
      ? requestPayload.isDefault
      : Boolean(requestPayload.defaultShipping) ||
        Boolean(requestPayload.defaultBilling);

  return (
    shouldSetAsDefault &&
    (!shouldEnforceB2BPermissions || Boolean(canSetDefaultAddress))
  );
};

export const canSetDefaultAddressInForm = ({
  isTemporaryCheckoutAddressMode,
  shouldEnforceB2BPermissions,
  canSetDefaultAddress,
}: {
  isTemporaryCheckoutAddressMode: boolean;
  shouldEnforceB2BPermissions: boolean;
  canSetDefaultAddress?: boolean;
}): boolean => {
  return (
    !isTemporaryCheckoutAddressMode &&
    (!shouldEnforceB2BPermissions || Boolean(canSetDefaultAddress))
  );
};

export const getSanitizedAddressPayload = ({
  requestPayload,
  shouldEnforceB2BPermissions,
  canSetDefaultAddress,
}: {
  requestPayload: CustomerAddressesModel;
  shouldEnforceB2BPermissions: boolean;
  canSetDefaultAddress?: boolean;
}): CustomerAddressesModel => {
  if (
    !shouldOmitDefaultFlagsFromPayload(
      shouldEnforceB2BPermissions,
      canSetDefaultAddress
    )
  ) {
    return requestPayload;
  }

  const sanitizedPayload = { ...requestPayload };
  delete sanitizedPayload.defaultShipping;
  delete sanitizedPayload.defaultBilling;
  delete sanitizedPayload.isDefault;

  return sanitizedPayload;
};

export const resolveUpdateAddressAlertKey = ({
  shouldEnforceB2BPermissions,
  canEditAddress,
  isB2BFlow,
  requestPayload,
}: {
  shouldEnforceB2BPermissions: boolean;
  canEditAddress?: boolean;
  isB2BFlow?: boolean;
  requestPayload: CustomerAddressesModel;
}): AddressValidationAlertKey | undefined => {
  if (shouldEnforceB2BPermissions && !canEditAddress) {
    return 'noPermissionEditAddresses';
  }

  if (hasSingleDefaultTypeViolation(isB2BFlow, requestPayload)) {
    return 'companyAddressSingleDefaultType';
  }

  return undefined;
};

export const resolveCreateAddressAlertKey = ({
  shouldEnforceB2BPermissions,
  canCreateAddress,
  isB2BFlow,
  requestPayload,
}: {
  shouldEnforceB2BPermissions: boolean;
  canCreateAddress?: boolean;
  isB2BFlow?: boolean;
  requestPayload: CustomerAddressesModel;
}): AddressValidationAlertKey | undefined => {
  if (shouldEnforceB2BPermissions && !canCreateAddress) {
    return 'noPermissionCreateAddresses';
  }

  if (hasSingleDefaultTypeViolation(isB2BFlow, requestPayload)) {
    return 'companyAddressSingleDefaultType';
  }

  return undefined;
};

export const resolveAddressFormErrorMessage = (error: unknown): string => {
  if (error instanceof Error && error.message) {
    return error.message;
  }

  if (typeof error === 'string' && error.trim()) {
    return error;
  }

  return 'Unknown error';
};

type ResolveB2BDefaultCheckBoxRulesArgs = {
  isB2BFlow?: boolean;
  showShippingCheckBox?: boolean;
  showBillingCheckBox?: boolean;
  shippingCheckBoxValue?: boolean;
  billingCheckBoxValue?: boolean;
  addressId?: string;
  hasDefaultShippingAddress?: boolean;
  hasDefaultBillingAddress?: boolean;
};

const resolveBaseCheckBoxRules = ({
  showShippingCheckBox,
  showBillingCheckBox,
  shippingCheckBoxValue,
  billingCheckBoxValue,
}: ResolveB2BDefaultCheckBoxRulesArgs): B2BDefaultCheckBoxRules => ({
  showShipping: Boolean(showShippingCheckBox),
  showBilling: Boolean(showBillingCheckBox),
  shippingDefaultValue: shippingCheckBoxValue ?? false,
  billingDefaultValue: billingCheckBoxValue ?? false,
});

type B2BCreateDefaultCaseKey =
  | 'none'
  | 'shippingOnly'
  | 'billingOnly'
  | 'both';

const B2B_CREATE_DEFAULT_RULES: Record<
  B2BCreateDefaultCaseKey,
  B2BDefaultCheckBoxRules
> = {
  none: {
    showShipping: true,
    showBilling: true,
    shippingDefaultValue: false,
    billingDefaultValue: false,
  },
  shippingOnly: {
    showShipping: false,
    showBilling: true,
    shippingDefaultValue: false,
    billingDefaultValue: true,
  },
  billingOnly: {
    showShipping: true,
    showBilling: false,
    shippingDefaultValue: true,
    billingDefaultValue: false,
  },
  both: {
    showShipping: false,
    showBilling: false,
    shippingDefaultValue: false,
    billingDefaultValue: false,
  },
};

const resolveB2BCreateDefaults = ({
  hasDefaultShippingAddress,
  hasDefaultBillingAddress,
}: ResolveB2BDefaultCheckBoxRulesArgs): B2BDefaultCheckBoxRules => {
  const hasShipping = Boolean(hasDefaultShippingAddress);
  const hasBilling = Boolean(hasDefaultBillingAddress);

  let ruleKey: B2BCreateDefaultCaseKey = 'none';

  if (hasShipping && hasBilling) {
    ruleKey = 'both';
  } else if (hasShipping) {
    ruleKey = 'shippingOnly';
  } else if (hasBilling) {
    ruleKey = 'billingOnly';
  }

  return B2B_CREATE_DEFAULT_RULES[ruleKey];
};

export const resolveB2BDefaultCheckBoxRules = ({
  isB2BFlow,
  showShippingCheckBox,
  showBillingCheckBox,
  shippingCheckBoxValue,
  billingCheckBoxValue,
  addressId,
  hasDefaultShippingAddress,
  hasDefaultBillingAddress,
}: ResolveB2BDefaultCheckBoxRulesArgs): B2BDefaultCheckBoxRules => {
  const baseRules = resolveBaseCheckBoxRules({
    showShippingCheckBox,
    showBillingCheckBox,
    shippingCheckBoxValue,
    billingCheckBoxValue,
  });
  const isCreateMode = !addressId;

  // Outside the company address book an address may be the default shipping
  // and the default billing address at once, so the caller's values are used
  // as they are. Only the company flow below narrows them to a single type.
  if (!isB2BFlow) {
    return baseRules;
  }

  if (!isCreateMode) {
    return baseRules;
  }

  return resolveB2BCreateDefaults({
    hasDefaultShippingAddress,
    hasDefaultBillingAddress,
  });
};
