import { useState, useEffect } from 'preact/hooks';
import { getCustomerCompanyContext } from '@/account/api/getCustomerCompanyContext';

/**
 * Hook to determine customer type (B2B vs B2C).
 * Pass `enabled: false` to skip the company-context request entirely
 * (e.g. when the host page already knows B2B is off for this storefront).
 */
export const useCustomerType = (enabled: boolean = true) => {
  const [loading, setLoading] = useState<boolean>(enabled);
  const [isB2BCustomer, setIsB2BCustomer] = useState<boolean>(false);

  useEffect(() => {
    if (!enabled) {
      setIsB2BCustomer(false);
      setLoading(false);
      return;
    }

    let isSubscribed = true;
    setLoading(true);

    getCustomerCompanyContext()
      .then((isB2BContext) => {
        if (!isSubscribed) return;
        setIsB2BCustomer(isB2BContext);
      })
      .catch((error) => {
        console.error('[Account][useCustomerType] Failed to resolve company context', error);

        if (!isSubscribed) return;
        setIsB2BCustomer(false);
      })
      .finally(() => {
        if (!isSubscribed) return;
        setLoading(false);
      });

    return () => {
      isSubscribed = false;
    };
  }, [enabled]);

  return {
    isB2BCustomer,
    loading,
  };
};
