import { FunctionComponent } from 'preact';
import { useEffect, useRef, useState } from 'preact/hooks';
import { classes, Slot } from '@adobe-commerce/elsie/lib';
import { Button, InLineAlert } from '@adobe-commerce/elsie/components';
import { Form } from '@/account/components';
import { AddressFormWrapperProps, FieldsProps } from '@/account/types';
import { useText } from '@adobe-commerce/elsie/i18n';
import { useAddressForm } from '@/account/hooks/containers/useAddressForm';
import '@/account/components/AddressFormWrapper/AddressFormWrapper.css';
import { transformDefaultValuesAddresses } from '@/account/lib/transformDefaultValuesAddresses';

export const AddressFormWrapper: FunctionComponent<AddressFormWrapperProps> = ({
  hideActionFormButtons,
  formName = '',
  showFormLoader = false,
  showSaveCheckBox = false,
  saveCheckBoxValue = false,
  forwardFormRef,
  slots,
  addressesFormTitle,
  className,
  addressFormId,
  inputsDefaultValueSet,
  showShippingCheckBox = true,
  showBillingCheckBox = true,
  hasDefaultShippingAddress = false,
  hasDefaultBillingAddress = false,
  shippingCheckBoxValue = true,
  billingCheckBoxValue = true,
  isOpen,
  fieldIdPrefix,
  onSubmit,
  onCloseBtnClick,
  onSuccess,
  onError,
  onChange,
  isB2BFlow,
  enforceB2BPermissions,
  permissions,
}) => {
  const translations = useText({
    secondaryButton: 'Account.AddressForm.formText.secondaryButton',
    primaryButton: 'Account.AddressForm.formText.primaryButton',
    saveAddressBook: 'Account.AddressForm.formText.saveAddressBook',
    noPermissionEditAddresses:
      'Account.AddressForm.notifications.noPermissionEditAddresses',
    noPermissionCreateAddresses:
      'Account.AddressForm.notifications.noPermissionCreateAddresses',
  });

  const shouldEnforceB2BPermissions =
    Boolean(isB2BFlow) && enforceB2BPermissions !== false;
  const shouldShowSaveCheckBox =
    Boolean(showSaveCheckBox) &&
    !(Boolean(isB2BFlow) && !shouldEnforceB2BPermissions);

  const {
    inLineAlert,
    addressId,
    submitLoading,
    normalizeFieldsConfig,
    handleUpdateAddress,
    handleCreateAddress,
    handleOnCloseForm,
    handleSaveCheckBoxAddress,
    saveCheckBoxAddress,
    handleInputChange,
    regionOptions,
  } = useAddressForm({
    showFormLoader,
    addressFormId,
    inputsDefaultValueSet: transformDefaultValuesAddresses(
      inputsDefaultValueSet
    ),
    shippingCheckBoxValue,
    billingCheckBoxValue,
    showShippingCheckBox,
    showBillingCheckBox,
    hasDefaultShippingAddress,
    hasDefaultBillingAddress,
    saveCheckBoxValue,
    showSaveCheckBox: shouldShowSaveCheckBox,
    onSuccess,
    onError,
    onCloseBtnClick,
    formName,
    isB2BFlow,
    enforceB2BPermissions,
    permissions,
  });

  const isEditMode = Boolean(addressFormId);
  const canEditInB2B =
    !shouldEnforceB2BPermissions || Boolean(permissions?.canEditAddress);
  const canSetDefaultInB2B =
    !shouldEnforceB2BPermissions || Boolean(permissions?.canSetDefaultAddress);
  const canCreateInB2B =
    !shouldEnforceB2BPermissions || Boolean(permissions?.canCreateAddress);

  // Check if form should be disabled based on operation-specific B2B permissions.
  const isFormDisabled = isEditMode
    ? !canEditInB2B && !canSetDefaultInB2B
    : !canCreateInB2B;
  const noPermissionMessage = isEditMode
    ? translations.noPermissionEditAddresses
    : translations.noPermissionCreateAddresses;

  const [formKey, setFormKey] = useState(0);
  const previousDefaultValuesRef = useRef<string | null>(null);

  // Re-mount form only when the default values really change. Comparing by
  // object identity remounts the form on every parent re-render (the address
  // list is re-created on each refetch), which drops focus and typed values.
  useEffect(() => {
    const serializedDefaultValues = JSON.stringify(
      inputsDefaultValueSet ?? null
    );

    if (previousDefaultValuesRef.current === serializedDefaultValues) return;

    const isInitialRun = previousDefaultValuesRef.current === null;

    previousDefaultValuesRef.current = serializedDefaultValues;

    if (isInitialRun) return;

    setFormKey((prevKey) => prevKey + 1);
  }, [inputsDefaultValueSet]);

  if (!isOpen) return null;

  // Show no permission message if B2B user doesn't have required rights
  if (isFormDisabled) {
    return (
      <div className={classes(['account-address-form-wrapper', className])}>
        {addressesFormTitle ? (
          <div
            className="account-address-form-wrapper__title"
            data-testid="addressesFormTitle"
          >
            {addressesFormTitle}
          </div>
        ) : null}
        <InLineAlert
          data-testid="noPermissionAlert"
          className="account-address-form-wrapper__notification"
          type="warning"
          variant="secondary"
          heading={noPermissionMessage}
        />
      </div>
    );
  }

  return (
    <div className={classes(['account-address-form-wrapper', className])}>
      {addressesFormTitle ? (
        <div
          className="account-address-form-wrapper__title"
          data-testid="addressesFormTitle"
        >
          {addressesFormTitle}
        </div>
      ) : null}
      {inLineAlert.text ? (
        <InLineAlert
          data-testid="inLineAlert"
          className="account-address-form-wrapper__notification"
          type={inLineAlert.type}
          variant="secondary"
          heading={inLineAlert.text}
          icon={inLineAlert.icon}
        />
      ) : null}
      <Form
        key={formKey}
        regionOptions={regionOptions}
        forwardFormRef={forwardFormRef}
        slots={slots}
        className="account-address-form"
        name={formName || 'addressesForm'}
        fieldsConfig={normalizeFieldsConfig as FieldsProps[]}
        onSubmit={
          onSubmit || (addressId ? handleUpdateAddress : handleCreateAddress)
        }
        setInputChange={handleInputChange}
        loading={submitLoading}
        showFormLoader={showFormLoader}
        showSaveCheckBox={shouldShowSaveCheckBox}
        handleSaveCheckBoxAddress={handleSaveCheckBoxAddress}
        saveCheckBoxAddress={saveCheckBoxAddress}
        onChange={onChange}
        fieldIdPrefix={fieldIdPrefix}
      >
        {addressId ? (
          <input
            type="hidden"
            name="addressId"
            value={addressId}
            data-testid="hidden_test_id"
          />
        ) : null}
        {!hideActionFormButtons ? (
          <div
            className={classes([
              'dropin-field account-address-form-wrapper__buttons',
              [
                'account-address-form-wrapper__buttons--empty',
                shouldShowSaveCheckBox,
              ],
            ])}
          >
            {slots?.AddressFormActions ? (
              <Slot
                data-testid="addressFormActions"
                name="AddressFormActions"
                slot={slots.AddressFormActions}
                context={{
                  handleUpdateAddress,
                  handleCreateAddress,
                  addressId,
                }}
              />
            ) : (
              <>
                {!shouldShowSaveCheckBox ? (
                  <>
                    <Button
                      // @ts-ignore
                      type={'button'}
                      onClick={handleOnCloseForm}
                      variant="secondary"
                      disabled={submitLoading || isFormDisabled}
                    >
                      {translations.secondaryButton}
                    </Button>
                    <Button disabled={submitLoading || isFormDisabled}>
                      {translations.primaryButton}
                    </Button>
                  </>
                ) : null}
              </>
            )}
          </div>
        ) : null}
      </Form>
    </div>
  );
};
