import { useState, useEffect } from 'preact/hooks';
import { getCustomerRolePermissions } from '@/account/api/getCustomerRolePermissions';
import {
  getDefaultCompanyAddressPermissions,
} from '@/account/lib/companyAddressPermissionsResolver';

/**
 * Company address-specific permissions interface
 */
export interface CompanyAddressPermissions {
  canAccessAddressBook: boolean;
  canViewAddress: boolean;
  canCreateAddress: boolean;
  canEditAddress: boolean;
  canDeleteAddress: boolean;
  canSetDefaultAddress: boolean;
  loading: boolean;
}

/**
 * Hook to fetch company address management permissions.
 * Pass `enabled: false` to skip the role-permissions request entirely
 * (e.g. when the host page already knows B2B is off for this storefront).
 */
export const useCompanyAddressPermissions = (
  enabled: boolean = true
): CompanyAddressPermissions => {
  const [loading, setLoading] = useState<boolean>(enabled);
  const [permissions, setPermissions] = useState<
    Omit<CompanyAddressPermissions, 'loading'>
  >(getDefaultCompanyAddressPermissions());

  useEffect(() => {
    if (!enabled) {
      setPermissions(getDefaultCompanyAddressPermissions());
      setLoading(false);
      return;
    }

    let isSubscribed = true;
    setLoading(true);

    getCustomerRolePermissions()
      .then((resolvedPermissions) => {
        if (!isSubscribed) return;
        setPermissions(resolvedPermissions);
      })
      .catch((error) => {
        console.error(
          '[Account][useCompanyAddressPermissions] Failed to resolve role permissions',
          error
        );

        if (!isSubscribed) return;

        setPermissions(getDefaultCompanyAddressPermissions());
      })
      .finally(() => {
        if (!isSubscribed) return;
        setLoading(false);
      });

    return () => {
      isSubscribed = false;
    };
  }, [enabled]);

  return {
    ...permissions,
    loading,
  };
};
