import { useState, useEffect, useCallback } from 'preact/hooks';
import {
  getAttributesForm,
  getCustomerAddress,
  removeCustomerAddress,
  getCompanyAddressBook,
  deleteCompanyAddress,
} from '@/account/api/';
import { CustomerAddressesModel } from '@/account/data/models';
import { checkIsFunction } from '@/account/lib/checkIsFunction';
import { KeysSortOrderProps, useAddressesProps } from '@/account/types';
import {
  resolveAddressesContextMode,
  resolveEnforceB2BPermissions,
  resolveHasB2BContainerAccess,
  resolveIsAddressSelectionLocked,
  resolveIsB2BCandidate,
  resolveIsB2BFlow,
  resolveIsB2BWithoutViewAccess,
  resolveIsCheckoutContext,
  shouldApplyB2BAddressBookFlow,
  shouldReturnEmptyWithinAddressBook,
  shouldSkipAddressFetchForCustomerType,
  shouldSkipAddressFetchForPermissions,
} from '@/account/lib/addressFlowRules';
import { manageAddressDeletion } from '@/account/lib/manageAddressDeletion';
import { defaultAttributePreset } from '@/account/configs/defaultAttributePreset.config';
import { convertToCamelCase } from '@/account/lib/convertCase';
import sortingAddressesList from '@/account/lib/sortingAddressesList';
import { filterB2BCheckoutAddressesByType } from '../../lib/filterB2BCheckoutAddressesByType';
import { useCustomerType } from '@/account/hooks/useCustomerType';
import { useCompanyAddressPermissions } from '@/account/hooks/useCompanyAddressPermissions';
import {
  isEmpty,
  resolveAddressSelectionPayloadData,
} from '@/account/lib/addressSelectionPayloadRules';

export const useAddresses = ({
  b2bEnabled,
  selectShipping,
  selectBilling,
  selectable,
  contextMode,
  defaultSelectAddressId,
  onAddressData,
  minifiedView,
  routeAddressesPage,
  onSuccess,
}: useAddressesProps) => {
  // B2B context detection
  const { isB2BCustomer, loading: customerTypeLoading } = useCustomerType(
    Boolean(b2bEnabled)
  );
  const permissions = useCompanyAddressPermissions(Boolean(b2bEnabled));
  const isB2BCandidate = resolveIsB2BCandidate(b2bEnabled, isB2BCustomer);
  const resolvedContextMode = resolveAddressesContextMode(
    contextMode,
    selectable
  );
  const enforceB2BPermissions =
    resolveEnforceB2BPermissions(resolvedContextMode);
  const isCheckoutContext = resolveIsCheckoutContext(resolvedContextMode);

  const [selectedAddressOption, setSelectedAddressOption] =
    useState<string>('');
  const [isModalRendered, setIsModalRendered] = useState<boolean>(false);
  const [isFormRendered, setIsFormRendered] = useState<boolean>(false);
  const [loading, setLoading] = useState<boolean>(false);
  const [submitLoading, setSubmitLoading] = useState<boolean>(false);
  const [addNewAddress, setAddNewAddress] = useState<boolean>(false);
  const [addressId, setEditAddressId] = useState<string>('');
  const [addressesList, setAddressesList] = useState<CustomerAddressesModel[]>(
    []
  );
  const [keysSortOrder, setKeysSortOrder] = useState<KeysSortOrderProps[] | []>(
    []
  );
  const [isCompanyAddressBookEnabled, setIsCompanyAddressBookEnabled] =
    useState<boolean>(false);
  const [isCustomShippingAddressAllowed, setIsCustomShippingAddressAllowed] =
    useState<boolean>(true);

  const hasB2BContainerAccess = resolveHasB2BContainerAccess(permissions);
  const isB2BWithoutViewAccess = resolveIsB2BWithoutViewAccess({
    isB2BCandidate,
    isCompanyAddressBookEnabled,
    enforceB2BPermissions,
    permissions,
    hasB2BContainerAccess,
  });

  // Company address flow is active only when company address book is enabled.
  const isB2BFlow = resolveIsB2BFlow({
    isB2BCandidate,
    isCompanyAddressBookEnabled,
    isB2BWithoutViewAccess,
  });
  const isAddressSelectionLocked = resolveIsAddressSelectionLocked({
    isCheckoutContext,
    isB2BFlow,
    selectable,
    isCustomShippingAddressAllowed,
    selectShipping,
    selectBilling,
  });

  const applyAttributesSortOrder = useCallback(
    (attributesFormResponse: any[] | undefined) => {
      if (!attributesFormResponse) return;

      const result: KeysSortOrderProps[] = attributesFormResponse.map(
        ({ name, orderNumber, label }) => ({
          name: convertToCamelCase(name as string),
          orderNumber,
          label: !defaultAttributePreset.includes(name as string)
            ? label
            : null,
        })
      );

      setKeysSortOrder(result);
    },
    []
  );

  const getAddressesList = useCallback(async () => {
    const shouldWaitForCustomerType = shouldSkipAddressFetchForCustomerType({
      b2bEnabled,
      customerTypeLoading,
    });

    const shouldWaitForPermissions = shouldSkipAddressFetchForPermissions({
      isB2BCandidate,
      enforceB2BPermissions,
      permissionsLoading: permissions?.loading,
    });

    if (shouldWaitForCustomerType || shouldWaitForPermissions) {
      setLoading(true);
      return;
    }

    setLoading(true);

    try {
      if (shouldApplyB2BAddressBookFlow(isB2BCandidate)) {
        try {
          const result = await getCompanyAddressBook();
          const isAddressBookEnabled = Boolean(result?.addressBookEnabled);
          const allowCustomShippingAddress = Boolean(
            result?.addressBookCustomShippingAddressEnabled
          );

          setIsCompanyAddressBookEnabled(isAddressBookEnabled);
          setIsCustomShippingAddressAllowed(allowCustomShippingAddress);

          if (isAddressBookEnabled) {
            if (
              shouldReturnEmptyWithinAddressBook({
                enforceB2BPermissions,
                hasB2BContainerAccess,
              })
            ) {
              setAddressesList([]);
              return;
            }

            const attributesFormResponse = await getAttributesForm('shortRequest');
            applyAttributesSortOrder(attributesFormResponse);

            const addressItems = result?.addresses?.items ?? [];
            const normalizedAddressItems =
              filterB2BCheckoutAddressesByType({
                addresses: addressItems,
                isCheckoutContext,
                selectable,
                selectShipping,
                selectBilling,
              });

            if (minifiedView) {
              const defaultAddresses = normalizedAddressItems.filter(
                (el) => Boolean(el.defaultShipping) || Boolean(el.defaultBilling)
              );

              const addressesToSet = defaultAddresses.length
                ? defaultAddresses
                : normalizedAddressItems.slice(-1);

              setAddressesList(addressesToSet);
            } else {
              setAddressesList(normalizedAddressItems);
            }

            return;
          }
        } catch {
          // Graceful fallback: if company address-book endpoint is unavailable
          // or access is denied, continue with personal address flow.
          setIsCompanyAddressBookEnabled(false);
          setIsCustomShippingAddressAllowed(true);
        }
      }

      setIsCompanyAddressBookEnabled(false);
      setIsCustomShippingAddressAllowed(true);

      // B2C: Existing flow unchanged

      const [attributesFormResponse, addressResponse] = await Promise.all([
        getAttributesForm('shortRequest'),
        getCustomerAddress(),
      ]);

      applyAttributesSortOrder(attributesFormResponse);

      if (addressResponse) {
        if (minifiedView) {
          const defaultAddresses = addressResponse.filter(
            (el) => Boolean(el.defaultShipping) || Boolean(el.defaultBilling)
          );

          const addressesToSet = defaultAddresses.length
            ? defaultAddresses
            : addressResponse.slice(-1);

          setAddressesList(addressesToSet);
        } else {
          setAddressesList(addressResponse);
        }
      }
    } catch {
      // Keep UI behavior stable without emitting additional debug logs.
    } finally {
      setLoading(false);
    }
  }, [
    b2bEnabled,
    customerTypeLoading,
    minifiedView,
    isB2BCandidate,
    isCheckoutContext,
    selectable,
    selectShipping,
    selectBilling,
    enforceB2BPermissions,
    hasB2BContainerAccess,
    permissions?.loading,
    applyAttributesSortOrder,
  ]);

  useEffect(() => {
    getAddressesList();
  }, [getAddressesList]);

  useEffect(() => {
    const clearSelection = () => {
      setSelectedAddressOption('');
      setAddNewAddress(false);
      onAddressData?.({
        data: {},
        isDataValid: false,
      } as any);
    };

    if (!addressesList.length) {
      if (isAddressSelectionLocked) {
        clearSelection();
      }

      return;
    }

    // `0` is the caller saying it has no address to restore, so preselecting an
    // entry from the list would claim a selection the caller does not hold.
    if (defaultSelectAddressId === 0) {
      // A locked selection is restricted to company addresses, so there is no
      // new-address form to offer instead. Leave the list unselected and let the
      // customer pick, rather than highlighting an address the caller will then
      // refuse to act on.
      if (isAddressSelectionLocked) {
        clearSelection();

        return;
      }

      setAddNewAddress(true);
      setSelectedAddressOption('0');

      return;
    }

    // Otherwise prefer the requested address, falling back to the type-default,
    // which sortingAddressesList puts first.
    const item =
      addressesList.find((el) => {
        if (typeof defaultSelectAddressId === 'string') {
          return (
            el.uid === defaultSelectAddressId ||
            el.id?.toString() === defaultSelectAddressId
          );
        }
        return +el.id! === defaultSelectAddressId;
      }) ||
      sortingAddressesList(addressesList, selectShipping!, selectBilling!)[0];

    const { selectedItem, data } = resolveAddressSelectionPayloadData({
      item,
      isCheckoutContext,
      selectable,
      isB2BFlow,
    });

    const normalizeAddressData = {
      data,
      isDataValid: !isEmpty(selectedItem),
    };

    const selectedValue = item?.id?.toString() || item?.uid || '';
    setSelectedAddressOption(selectedValue);

    onAddressData?.(normalizeAddressData);
  }, [
    addressesList,
    defaultSelectAddressId,
    onAddressData,
    selectBilling,
    selectShipping,
    isAddressSelectionLocked,
    isCheckoutContext,
    selectable,
    isB2BFlow,
  ]);

  const setEditingAddressId = useCallback((id: string) => {
    setEditAddressId(id);
    setAddNewAddress(false);
  }, []);

  const handleSelectAddressOption = useCallback(
    (event: Event, item?: {} | CustomerAddressesModel | undefined) => {
      const value = (event?.target as HTMLInputElement).value;

      if (isAddressSelectionLocked && value === '0') {
        return;
      }

      const nextSibling = (event?.target as HTMLInputElement)
        .nextSibling as HTMLElement;

      setSelectedAddressOption(value);

      const { data } = resolveAddressSelectionPayloadData({
        item: item as CustomerAddressesModel | undefined,
        isCheckoutContext,
        selectable,
        isB2BFlow,
      });

      const normalizeAddressData = {
        data,
        isDataValid: !isEmpty(data),
      };

      onAddressData?.(normalizeAddressData);
      setAddNewAddress(value === '0');

      if (nextSibling) {
        nextSibling.focus();
        window.scrollBy(0, 100);
      }
    },
    [
      onAddressData,
      isAddressSelectionLocked,
      isCheckoutContext,
      selectable,
      isB2BFlow,
    ]
  );

  const handleRenderForm = useCallback(() => {
    setIsFormRendered(true);
  }, []);

  const onCloseBtnClick = useCallback(() => {
    setEditAddressId('');
    setIsFormRendered(false);
    setIsModalRendered(false);
  }, []);

  const handleRenderModal = useCallback(() => {
    setIsModalRendered(true);
  }, []);

  const removeAddress = useCallback(async () => {
    setSubmitLoading(true);

    try {
      if (isB2BFlow) {
        if (!permissions?.canDeleteAddress) return;

        // B2B: Use company address delete API
        await deleteCompanyAddress(addressId);
      } else {
        // B2C: Existing flow unchanged
        await manageAddressDeletion(addressId, addressesList);
        await removeCustomerAddress(+addressId);
      }

      onCloseBtnClick();
      await getAddressesList();
    } catch {
      // Keep UI behavior stable without emitting additional debug logs.
    } finally {
      setSubmitLoading(false);
    }
  }, [
    addressesList,
    addressId,
    onCloseBtnClick,
    getAddressesList,
    isB2BFlow,
    permissions?.canDeleteAddress,
  ]);

  const closeNewAddressForm = useCallback(() => {
    setAddNewAddress(false);
  }, []);

  const redirectToAddressesRoute = useCallback(() => {
    if (isAddressSelectionLocked) {
      return;
    }

    const isClientRoute =
      checkIsFunction(routeAddressesPage) && minifiedView && !addNewAddress;

    if (isClientRoute) {
      window.location.href = routeAddressesPage();
    } else {
      setAddNewAddress(true);
      setEditAddressId('');
    }
  }, [
    addNewAddress,
    routeAddressesPage,
    minifiedView,
    isAddressSelectionLocked,
  ]);

  const handleOnSuccess = useCallback(async () => {
    await getAddressesList();
    await onSuccess?.();
  }, [getAddressesList, onSuccess]);

  return {
    keysSortOrder,
    submitLoading,
    isModalRendered,
    isFormRendered,
    loading,
    addNewAddress,
    addressesList,
    addressId,
    handleRenderForm,
    handleRenderModal,
    removeAddress,
    onCloseBtnClick,
    setEditingAddressId,
    closeNewAddressForm,
    redirectToAddressesRoute,
    handleOnSuccess,
    handleSelectAddressOption,
    selectedAddressOption,
    permissions,
    isB2BFlow,
    enforceB2BPermissions,
    isAddressSelectionLocked,
  };
};
