import { CustomerAddressesModel } from '@/account/data/models';
import {
  CompanyAddressTypeEnum,
  type CompanyAddressType,
} from '@/account/types/api/companyAddress.types';

type FilterB2BCheckoutAddressesByTypeArgs = {
  addresses: CustomerAddressesModel[];
  isCheckoutContext: boolean;
  selectable?: boolean;
  selectShipping?: boolean;
  selectBilling?: boolean;
};

const resolveAddressType = (
  address: CustomerAddressesModel
): CompanyAddressType | undefined => {
  if (
    address?.addressType === CompanyAddressTypeEnum.SHIPPING ||
    address?.addressType === CompanyAddressTypeEnum.BILLING
  ) {
    return address.addressType;
  }

  const hasDefaultShipping = Boolean(address?.defaultShipping);
  const hasDefaultBilling = Boolean(address?.defaultBilling);

  if (hasDefaultShipping === hasDefaultBilling) {
    return undefined;
  }

  return hasDefaultShipping
    ? CompanyAddressTypeEnum.SHIPPING
    : CompanyAddressTypeEnum.BILLING;
};

export const filterB2BCheckoutAddressesByType = ({
  addresses,
  isCheckoutContext,
  selectable,
  selectShipping,
  selectBilling,
}: FilterB2BCheckoutAddressesByTypeArgs): CustomerAddressesModel[] => {
  if (!isCheckoutContext || !selectable) {
    return addresses;
  }

  const isShippingOnly = Boolean(selectShipping && !selectBilling);
  const isBillingOnly = Boolean(selectBilling && !selectShipping);

  if (!isShippingOnly && !isBillingOnly) {
    return addresses;
  }

  const expectedType: CompanyAddressType = isShippingOnly
    ? CompanyAddressTypeEnum.SHIPPING
    : CompanyAddressTypeEnum.BILLING;

  return addresses.filter(
    (address) => resolveAddressType(address) === expectedType
  );
};
