import { getOrderHistoryList, getStoreConfig } from '@/account/api';
import { OrderDetails } from '@/account/data/models';
import { UseOrdersListProps } from '@/account/types';
import { useCallback, useEffect, useState } from 'preact/hooks';
import { events } from '@adobe-commerce/event-bus';
import { useText } from '@adobe-commerce/elsie/i18n';

export const useOrdersList = ({
  ordersInMinifiedView,
  minifiedView,
  pageSize,
  selectedDate,
  selectedPage,
  searchText,
  handleSetFirstOrderDate,
  handleSetInLineAlert,
}: UseOrdersListProps) => {
  const translations = useText({
    searchError: 'Account.fullSizeView.OrdersList.OrdersListSearch.error',
  });

  const [orderHistoryListItems, setOrderHistoryListItems] = useState<
    OrderDetails[]
  >([]);
  const [pageInfo, setPageInfo] = useState<{
    totalPages: number;
    currentPage: number;
    pageSize: number;
  }>({ totalPages: 1, currentPage: 1, pageSize: 1 });
  const [loading, setLoading] = useState(false);
  const [placeholderImage, setPlaceholderImage] = useState('');
  const [refetchTrigger, setRefetchTrigger] = useState(0);
  const refetchOrders = useCallback(() => {
    setRefetchTrigger((prev) => prev + 1);
  }, []);

  useEffect(() => {
    getStoreConfig().then((response) => {
      setPlaceholderImage(response.baseMediaUrl);
    });
  }, []);

  // Listen for company context changes to refetch orders
  useEffect(() => {
    const companyContextEvent = events.on(
      'companyContext/changed',
      refetchOrders
    );

    return () => {
      companyContextEvent?.off();
    };
  }, [refetchOrders]);

  useEffect(() => {
    const abortController = new AbortController();

    setLoading(true);
    handleSetInLineAlert?.();

    getOrderHistoryList(
      minifiedView ? ordersInMinifiedView : pageSize,
      selectedDate,
      selectedPage,
      searchText,
      abortController.signal
    )
      .then((response) => {
        if (abortController.signal.aborted) return;
        if (!response?.items) {
          setOrderHistoryListItems([]);
          handleSetInLineAlert?.({
            type: 'error',
            text: translations.searchError,
          });
          return;
        }

        setPageInfo(response.pageInfo);
        setOrderHistoryListItems(response.items);
        handleSetFirstOrderDate?.(response.dateOfFirstOrder);
      })
      .catch(() => {
        if (abortController.signal.aborted) return;

        setOrderHistoryListItems([]);
        handleSetInLineAlert?.({
          type: 'error',
          text: translations.searchError,
        });
      })
      .finally(() => {
        if (abortController.signal.aborted) return;
        setLoading(false);
      });

    return () => {
      abortController.abort();
    };
  }, [
    handleSetFirstOrderDate,
    handleSetInLineAlert,
    minifiedView,
    ordersInMinifiedView,
    pageSize,
    selectedDate,
    selectedPage,
    searchText,
    refetchTrigger,
    translations.searchError,
  ]);

  return {
    loading,
    orderHistoryListItems,
    pageInfo,
    placeholderImage,
    refetchOrders,
  };
};
