import { AddressContextMode } from '@/account/types';

type AddressPermissionsFlags = {
  canAccessAddressBook?: boolean;
  canViewAddress?: boolean;
  loading?: boolean;
};

export const resolveAddressesContextMode = (
  contextMode?: AddressContextMode,
  selectable?: boolean
): AddressContextMode => {
  return contextMode || (selectable ? 'checkout' : 'addressBook');
};

export const resolveEnforceB2BPermissions = (
  resolvedContextMode: AddressContextMode
): boolean => {
  return resolvedContextMode === 'addressBook';
};

export const resolveIsCheckoutContext = (
  resolvedContextMode: AddressContextMode
): boolean => {
  return resolvedContextMode === 'checkout';
};

export const resolveIsB2BCandidate = (
  b2bEnabled?: boolean,
  isB2BCustomer?: boolean
): boolean => {
  return Boolean(b2bEnabled) && Boolean(isB2BCustomer);
};

export const resolveHasB2BContainerAccess = (
  permissions?: AddressPermissionsFlags
): boolean => {
  return (
    Boolean(permissions?.canAccessAddressBook) &&
    Boolean(permissions?.canViewAddress)
  );
};

export const resolveIsB2BWithoutViewAccess = ({
  isB2BCandidate,
  isCompanyAddressBookEnabled,
  enforceB2BPermissions,
  permissions,
  hasB2BContainerAccess,
}: {
  isB2BCandidate: boolean;
  isCompanyAddressBookEnabled: boolean;
  enforceB2BPermissions: boolean;
  permissions?: AddressPermissionsFlags;
  hasB2BContainerAccess: boolean;
}): boolean => {
  return (
    Boolean(isB2BCandidate) &&
    Boolean(isCompanyAddressBookEnabled) &&
    enforceB2BPermissions &&
    !permissions?.loading &&
    !hasB2BContainerAccess
  );
};

export const resolveIsB2BFlow = ({
  isB2BCandidate,
  isCompanyAddressBookEnabled,
  isB2BWithoutViewAccess,
}: {
  isB2BCandidate: boolean;
  isCompanyAddressBookEnabled: boolean;
  isB2BWithoutViewAccess: boolean;
}): boolean => {
  return (
    Boolean(isB2BCandidate) &&
    (isCompanyAddressBookEnabled || isB2BWithoutViewAccess)
  );
};

export const resolveIsAddressSelectionLocked = ({
  isCheckoutContext,
  isB2BFlow,
  selectable,
  isCustomShippingAddressAllowed,
  selectShipping,
  selectBilling,
}: {
  isCheckoutContext: boolean;
  isB2BFlow: boolean;
  selectable?: boolean;
  isCustomShippingAddressAllowed: boolean;
  selectShipping?: boolean;
  selectBilling?: boolean;
}): boolean => {
  // "Allow Custom Shipping Address" only ever unlocks shipping selection —
  // a billing-only instance has no equivalent flag and must stay locked to company addresses.
  const isBillingOnlySelection = Boolean(selectBilling) && !selectShipping;

  return (
    isCheckoutContext &&
    Boolean(isB2BFlow) &&
    Boolean(selectable) &&
    (isBillingOnlySelection || !isCustomShippingAddressAllowed)
  );
};

export const shouldSkipAddressFetchForCustomerType = ({
  b2bEnabled,
  customerTypeLoading,
}: {
  b2bEnabled?: boolean;
  customerTypeLoading: boolean;
}): boolean => {
  return Boolean(b2bEnabled) && customerTypeLoading;
};

export const shouldSkipAddressFetchForPermissions = ({
  isB2BCandidate,
  enforceB2BPermissions,
  permissionsLoading,
}: {
  isB2BCandidate: boolean;
  enforceB2BPermissions: boolean;
  permissionsLoading?: boolean;
}): boolean => {
  return isB2BCandidate && enforceB2BPermissions && Boolean(permissionsLoading);
};

export const shouldReturnEmptyForRestrictedB2B = ({
  isB2BCandidate,
  enforceB2BPermissions,
  hasB2BContainerAccess,
}: {
  isB2BCandidate: boolean;
  enforceB2BPermissions: boolean;
  hasB2BContainerAccess: boolean;
}): boolean => {
  return isB2BCandidate && enforceB2BPermissions && !hasB2BContainerAccess;
};

export const shouldApplyB2BAddressBookFlow = (
  isB2BCandidate: boolean
): boolean => {
  return isB2BCandidate;
};

export const shouldReturnEmptyWithinAddressBook = ({
  enforceB2BPermissions,
  hasB2BContainerAccess,
}: {
  enforceB2BPermissions: boolean;
  hasB2BContainerAccess: boolean;
}): boolean => {
  return enforceB2BPermissions && !hasB2BContainerAccess;
};
